// Render the design model with Graphviz automatic layout, then export a standalone SVG and PNG.
// Input is generated by build_design_docs.py; the Mermaid source remains alongside the diagram.
const fs = require('node:fs');
const path = require('node:path');
const { instance } = require('../.tools/design-render/node_modules/@viz-js/viz');
const { Resvg } = require('../.tools/design-render/node_modules/@resvg/resvg-js');
const root = path.resolve(__dirname, '..');
const model = JSON.parse(fs.readFileSync(path.join(root, 'docs/数据库ER.model.json'), 'utf8'));
const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const card = { '||': '1', 'o|': '0..1', 'o{': '0..*' };
const lines = ['digraph ER {', 'graph [rankdir=LR,bgcolor="#F3F6FA",pad=0.45,nodesep=0.55,ranksep=1.25,fontname="Arial",label="Municipal access platform · RBAC0 ER",labelloc=t,fontsize=22];', 'node [shape=plain,fontname="Arial"];', 'edge [dir=none,color="#7E97AA",fontname="Arial",fontsize=10,labeldistance=2.2];'];
for (const [name, fields] of Object.entries(model.entities)) {
  const rows = fields.map(field => `<TR><TD ALIGN="LEFT">${escape(field)}</TD></TR>`).join('');
  lines.push(`${name} [label=<<TABLE BORDER="1" COLOR="#AFC2D1" CELLBORDER="0" CELLSPACING="0" CELLPADDING="8" BGCOLOR="white"><TR><TD BGCOLOR="#16324F"><FONT COLOR="white"><B>${name}</B></FONT></TD></TR>${rows}</TABLE>>];`);
}
for (const [left, a, b, right, label] of model.relations) {
  lines.push(`${left} -> ${right} [taillabel="${card[a]}",headlabel="${card[b]}",label="${label.replaceAll('_', ' ')}",${label === 'source' || label === 'templates' ? 'style=dashed,color="#A4B5C2",constraint=false' : 'penwidth=1.3'}];`);
}
lines.push('}');
(async () => {
  const graphviz = await instance();
  const svg = graphviz.renderString(lines.join('\n'), { format: 'svg', engine: 'dot' });
  fs.writeFileSync(path.join(root, 'docs/数据库ER.svg'), svg);
  fs.writeFileSync(path.join(root, 'docs/数据库ER.png'), new Resvg(svg, { fitTo: { mode: 'width', value: 2200 } }).render().asPng());
  console.log('Complete ER relationships rendered to SVG and PNG.');
})();
